SELECT "APPLICATION" AS "APPLICATION", "STATUS_INFO" AS "STATUS_INFO", COUNT(*) AS count, AVG("JOB_DURATION_d") AS "AVG(JOB_DURATION_d)", max("MAX_JOBS_COUNT_d") AS "MAX(MAX_JOBS_COUNT_d)" 
FROM "default"."jobs" 
WHERE "@timestamp_date" >= TIMESTAMP '2026-03-25 00:00:00.000000' AND "@timestamp_date" < TIMESTAMP '2026-04-02 00:00:00.000000' AND ("STATUS_INFO" NOT IN ('SUCCESS')) GROUP BY "APPLICATION", "STATUS_INFO" ORDER BY "AVG(JOB_DURATION_d)" DESC 
 LIMIT 100;